step_3_advanced.custom_nginx_configuration:
# Configuration personnalisée pour Panel IPTV

# Augmenter les timeouts pour les longues requêtes
proxy_connect_timeout 300;
proxy_send_timeout 300;
proxy_read_timeout 300;
send_timeout 300;

# Augmenter la taille maximale du body
client_max_body_size 500M;

# Headers pour WebSocket et streaming
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection "upgrade";
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_set_header X-Forwarded-Host $host;
proxy_set_header X-Forwarded-Port $server_port;

# Cache pour les assets statiques
location ~* \.(jpg|jpeg|png|gif|ico|css|js|svg|woff|woff2|ttf|eot)$ {
    proxy_pass http://192.168.1.100:80;
    proxy_cache_valid 200 7d;
    proxy_cache_valid 404 1m;
    add_header Cache-Control "public, max-age=604800, immutable";
}

# Désactiver le cache pour les requêtes API
location /api/ {
    proxy_pass http://192.168.1.100:80;
    proxy_cache off;
    add_header Cache-Control "no-store, no-cache, must-revalidate";
}

# Support pour les playlists M3U
location ~ \.(m3u|m3u8)$ {
    proxy_pass http://192.168.1.100:80;
    add_header Content-Type "application/vnd.apple.mpegurl";
    add_header Cache-Control "no-cache";
}

examples.config:
location /admin {
    allow 192.168.1.0/24;
    deny all;
    proxy_pass http://192.168.1.100:80;
}

limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;

location /api/ {
    limit_req zone=api_limit burst=20 nodelay;
    proxy_pass http://192.168.1.100:80;
}

add_header X-Frame-Options "SAMEORIGIN" always;
add_header X-Content-Type-Options "nosniff" always;
add_header X-XSS-Protection "1; mode=block" always;
add_header Referrer-Policy "no-referrer-when-downgrade" always;

load_balancing.upstream_config:
upstream iptv_backend {
    least_conn;
    server 192.168.1.100:80 max_fails=3 fail_timeout=30s;
    server 192.168.1.101:80 max_fails=3 fail_timeout=30s;
    server 192.168.1.102:80 backup;
}

location / {
    proxy_pass http://iptv_backend;
}

best_practices.config:
location /login {
    limit_req zone=login_limit burst=5 nodelay;
    proxy_pass http://192.168.1.100:80;
}
